        [STAThread]
        static void Main(string[] args)
        {
            try
            {
                System.Net.ServicePointManager.SecurityProtocol = (System.Net.SecurityProtocolType)3072 | System.Net.SecurityProtocolType.Tls11 | System.Net.SecurityProtocolType.Tls;
                SetProcessDPIAware();
            }
            catch { }

            bool isNewInstance;
            using (Mutex mutex = new Mutex(true, "EktaHRAttendanceAgentSingleInstanceMutex", out isNewInstance))
            {
                if (!isNewInstance)
                {
                    try
                    {
                        PostMessage((IntPtr)0xffff, WM_SHOW_EKTA_AGENT, IntPtr.Zero, IntPtr.Zero);
                    }
                    catch { }
                    return;
                }

                Application.EnableVisualStyles();
                Application.SetCompatibleTextRenderingDefault(false);

                try
                {
                    string hostname = Environment.MachineName;
                    string sysUser = Environment.UserName;
                    string deviceId = "WIN-PC-" + hostname.ToUpper();

                    LoadLocalConfig(ref ServerHttpUrl, ref ServerWsUrl);

                    if (args != null && args.Length > 0)
                    {
                        foreach (string arg in args)
                        {
                            if (arg.StartsWith("ws://") || arg.StartsWith("wss://")) ServerWsUrl = arg.Trim();
                            else if (arg.StartsWith("http://") || arg.StartsWith("https://")) ServerHttpUrl = arg.Trim();
                        }
                    }

                    // Run Form
                    Application.Run(new EktaAgentForm(hostname, sysUser, deviceId, ServerHttpUrl, ServerWsUrl));
                }
                catch (Exception ex)
                {
                    File.WriteAllText("crash_log.txt", ex.ToString());
                    MessageBox.Show("Startup error: " + ex.Message, "ektaHr Agent Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                }
            }
        }

        private static void LoadLocalConfig(ref string httpUrl, ref string wsUrl)
        {
            try
            {
                string domainFile = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "domain.txt");
                if (!File.Exists(domainFile)) domainFile = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "domain_config.txt");
                if (File.Exists(domainFile))
                {
                    string dom = File.ReadAllText(domainFile).Trim().TrimEnd('/');
                    if (!string.IsNullOrEmpty(dom))
                    {
                        string cleanDom = dom.Replace("http://", "").Replace("https://", "").Replace("ws://", "").Replace("wss://", "");
                        httpUrl = "https://" + cleanDom;
                        wsUrl = "wss://" + cleanDom;
                        return;
                    }
                }

                if (File.Exists("config.json"))
                {
                    string json = File.ReadAllText("config.json");
                    string savedHttp = ExtractJsonValue(json, "httpUrl");
                    string savedWs = ExtractJsonValue(json, "wsUrl");

                    // If cached config contains legacy port :9000 or old IP 192.168.x.x, PURGE IT!
                    if (!string.IsNullOrEmpty(savedHttp) && (savedHttp.Contains(":9000") || savedHttp.Contains("192.168.0.31") || savedHttp.Contains("192.168.16.121")))
                    {
                        try { File.Delete("config.json"); } catch { }
                        savedHttp = "";
                        savedWs = "";
                    }

                    if (!string.IsNullOrEmpty(savedHttp) && !savedHttp.Contains("localhost") && !savedHttp.Contains("127.0.0.1"))
                        httpUrl = savedHttp;
                    if (!string.IsNullOrEmpty(savedWs) && !savedWs.Contains("localhost") && !savedWs.Contains("127.0.0.1"))
                        wsUrl = savedWs;
                }
                else if (File.Exists("config.txt"))
                {
                    string txt = File.ReadAllText("config.txt").Trim();
                    if (txt.Contains(":9000") || txt.Contains("192.168.0.31") || txt.Contains("192.168.16.121"))
                    {
                        try { File.Delete("config.txt"); } catch { }
                    }
                    else if ((txt.StartsWith("ws://") || txt.StartsWith("wss://")) && !txt.Contains("localhost") && !txt.Contains("127.0.0.1"))
                    {
                        wsUrl = txt;
                    }
                }

                if (httpUrl.Contains(":9000") || httpUrl.Contains("192.168.0.31") || httpUrl.Contains("192.168.16.121"))
                {
                    httpUrl = "https://track.ektahr.com";
                    wsUrl = "wss://track.ektahr.com";
                }
            }
            catch { }
        }

