        private static string GetDailyStatsFilename(string userEmail)
        {
            string cleanUser = (string.IsNullOrEmpty(userEmail) ? "user" : userEmail).Replace("@", "_").Replace(".", "_").Replace(" ", "_");
            string todayDate = DateTime.Now.ToString("yyyyMMdd");
            return "daily_session_" + cleanUser + "_" + todayDate + ".json";
        }

        public static void LoadDailyStats(string userEmail)
        {
            try
            {
                string filename = GetDailyStatsFilename(userEmail);
                if (File.Exists(filename))
                {
                    string json = File.ReadAllText(filename);
                    string savedCheckIn = ExtractJsonValue(json, "checkInTime");
                    int savedShift = ExtractInt(json, "shiftSeconds");
                    int savedActive = ExtractInt(json, "activeSeconds");
                    long savedKeys = ExtractLong(json, "totalKeystrokes");
                    long savedClicks = ExtractLong(json, "totalMouseClicks");

                    if (!string.IsNullOrEmpty(savedCheckIn)) CheckInTime = savedCheckIn;
                    else CheckInTime = DateTime.Now.ToString("hh:mm tt");

                    ActiveSeconds = savedActive;
                    TotalKeystrokes = savedKeys;
                    TotalMouseClicks = savedClicks;
                }
                else
                {
                    CheckInTime = DateTime.Now.ToString("hh:mm tt");
                    ShiftSeconds = 0;
                    ActiveSeconds = 0;
                    TotalKeystrokes = 0;
                    TotalMouseClicks = 0;
                    SaveDailyStats();
                }

                RecalculateShiftSeconds();
            }
            catch
            {
                CheckInTime = DateTime.Now.ToString("hh:mm tt");
                RecalculateShiftSeconds();
            }
        }

        public static void RecalculateShiftSeconds()
        {
            try
            {
                if (!string.IsNullOrEmpty(CheckInTime))
                {
                    DateTime checkInDt;
                    if (DateTime.TryParse(CheckInTime, out checkInDt))
                    {
                        DateTime now = DateTime.Now;
                        DateTime fullCheckIn = new DateTime(now.Year, now.Month, now.Day, checkInDt.Hour, checkInDt.Minute, checkInDt.Second);
                        if (fullCheckIn <= now)
                        {
                            ShiftSeconds = (int)(now - fullCheckIn).TotalSeconds;
                        }
                    }
                }
            }
            catch { }
        }

        public static void SaveDailyStats()
        {
            try
            {
                if (string.IsNullOrEmpty(LoggedUser)) return;
                string filename = GetDailyStatsFilename(LoggedUser);
                string json = "{" +
                    "\"checkInTime\":\"" + EscapeJson(CheckInTime) + "\"," +
                    "\"shiftSeconds\":" + ShiftSeconds + "," +
                    "\"activeSeconds\":" + ActiveSeconds + "," +
                    "\"totalKeystrokes\":" + TotalKeystrokes + "," +
                    "\"totalMouseClicks\":" + TotalMouseClicks +
                    "}";
                File.WriteAllText(filename, json);
            }
            catch { }
        }

        public static string GetLocalIPAddress()
        {
            try
            {
                var host = System.Net.Dns.GetHostEntry(System.Net.Dns.GetHostName());
                foreach (var ip in host.AddressList)
                {
                    if (ip.AddressFamily == System.Net.Sockets.AddressFamily.InterNetwork)
                    {
                        return ip.ToString();
                    }
                }
            }
            catch { }
            return "127.0.0.1";
        }

        private static string DiscoverViaUdpBroadcast()
        {
            try
            {
                using (var client = new System.Net.Sockets.UdpClient())
                {
                    client.EnableBroadcast = true;
                    client.Client.ReceiveTimeout = 400;
                    byte[] reqBytes = System.Text.Encoding.UTF8.GetBytes("EKTA_DISCOVER");
                    var targetEp = new System.Net.IPEndPoint(System.Net.IPAddress.Broadcast, 9002);
                    client.Send(reqBytes, reqBytes.Length, targetEp);

                    var remoteEp = new System.Net.IPEndPoint(System.Net.IPAddress.Any, 0);
                    byte[] respBytes = client.Receive(ref remoteEp);
                    string respStr = System.Text.Encoding.UTF8.GetString(respBytes).Trim();

                    if (respStr.StartsWith("EKTA_SERVER:"))
                    {
                        string portStr = respStr.Replace("EKTA_SERVER:", "").Trim();
                        string serverIp = remoteEp.Address.ToString();
                        return "http://" + serverIp + ":" + (string.IsNullOrEmpty(portStr) ? "2005" : portStr);
                    }
                }
            }
            catch { }
            return null;
        }

        private static bool PingHealthEndpointFast(string url)
        {
            if (string.IsNullOrEmpty(url)) return false;
            try
            {
                System.Net.ServicePointManager.SecurityProtocol = (System.Net.SecurityProtocolType)3072 | System.Net.SecurityProtocolType.Tls11 | System.Net.SecurityProtocolType.Tls;
                System.Net.ServicePointManager.DefaultConnectionLimit = 500;
                System.Net.ServicePointManager.Expect100Continue = false;

                string targetUrl = url.TrimEnd('/');
                if (!targetUrl.EndsWith("/health") && !targetUrl.EndsWith("/api/v1/health"))
                {
                    targetUrl += "/api/v1/health";
                }

                var req = (System.Net.HttpWebRequest)System.Net.WebRequest.Create(targetUrl);
                req.Timeout = 1500;
                req.ReadWriteTimeout = 1500;
                req.Method = "GET";
                using (var resp = (System.Net.HttpWebResponse)req.GetResponse())
                {
                    return resp.StatusCode == System.Net.HttpStatusCode.OK;
                }
            }
            catch
            {
                try
                {
                    var req2 = (System.Net.HttpWebRequest)System.Net.WebRequest.Create(url.TrimEnd('/') + "/health");
                    req2.Timeout = 1500;
                    req2.ReadWriteTimeout = 1500;
                    req2.Method = "GET";
                    using (var resp2 = (System.Net.HttpWebResponse)req2.GetResponse())
                    {
                        return resp2.StatusCode == System.Net.HttpStatusCode.OK;
                    }
                }
                catch
                {
                    if (url.Contains("track.ektahr.com")) return true;
                    return false;
                }
            }
        }

        public static string DiscoverActiveLanServerUrl()
        {
            // 1. Instant UDP Broadcast Discovery (10ms speed)
            string udpUrl = DiscoverViaUdpBroadcast();
            if (!string.IsNullOrEmpty(udpUrl) && PingHealthEndpointFast(udpUrl)) return udpUrl;

            // 2. Try loopbacks & cached config
            string localIp = GetLocalIPAddress();
            List<string> quickCandidates = new List<string>();

            if (!string.IsNullOrEmpty(ServerHttpUrl)) quickCandidates.Add(ServerHttpUrl);
            quickCandidates.Add("https://track.ektahr.com");
            quickCandidates.Add("http://127.0.0.1:2005");
            quickCandidates.Add("http://localhost:2005");
            quickCandidates.Add("http://192.168.0.31:2005");
            quickCandidates.Add("http://192.168.1.31:2005");
            if (!string.IsNullOrEmpty(localIp)) quickCandidates.Add("http://" + localIp + ":2005");

            foreach (string candidate in quickCandidates)
            {
                if (PingHealthEndpointFast(candidate)) return candidate;
            }

            // 3. High-speed parallel LAN Subnet Auto-Scanner
            if (!string.IsNullOrEmpty(localIp) && localIp.Contains("."))
            {
                string subnetPrefix = localIp.Substring(0, localIp.LastIndexOf('.') + 1);
                string foundUrl = null;
                object lockObj = new object();

                System.Threading.Tasks.Parallel.For(1, 255, new System.Threading.Tasks.ParallelOptions { MaxDegreeOfParallelism = 100 }, i =>
                {
                    if (foundUrl != null) return;
                    string target = "http://" + subnetPrefix + i + ":2005";
                    if (PingHealthEndpointFast(target))
                    {
                        lock (lockObj)
                        {
                            if (foundUrl == null) foundUrl = target;
                        }
                    }
                });

                if (!string.IsNullOrEmpty(foundUrl)) return foundUrl;
            }

            return null;
        }

        // ================= AUTHENTICATION & DEVICE REGISTRATION =================
        public static bool ValidateAndRegister(string email, string password, string userEnteredUrl, out string displayName, out string errorMsg)
        {
            displayName = email;
            errorMsg = "";

            if (string.IsNullOrEmpty(ServerHttpUrl) || ServerHttpUrl.Contains(":9000") || ServerHttpUrl.Contains("192.168.0.31") || ServerHttpUrl.Contains("192.168.16.121"))
            {
                ServerHttpUrl = "https://track.ektahr.com";
                ServerWsUrl = "wss://track.ektahr.com";
            }

            List<string> candidateUrls = new List<string>();

            // 1. Option B: Read domain.txt / domain_config.txt / server_ip.txt / server.txt if present next to EXE
            try
            {
                string[] legacyFiles = new string[] { "server_ip.txt", "server.txt", "admin_config.txt" };
                foreach (string f in legacyFiles)
                {
                    string path = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, f);
                    if (File.Exists(path))
                    {
                        string content = File.ReadAllText(path);
                        if (content.Contains(":9000") || content.Contains("192.168.0.31") || content.Contains("192.168.16.121"))
                        {
                            try { File.Delete(path); } catch { }
                        }
                    }
                }

                string ipTxt = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "domain.txt");
                if (!File.Exists(ipTxt)) ipTxt = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "domain_config.txt");
                if (!File.Exists(ipTxt)) ipTxt = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "server_ip.txt");
                if (!File.Exists(ipTxt)) ipTxt = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "server.txt");
                if (File.Exists(ipTxt))
                {
                    string fileUrl = File.ReadAllText(ipTxt).Trim();
                    if (fileUrl.Contains(":9000") || fileUrl.Contains("192.168.0.31") || fileUrl.Contains("192.168.16.121"))
                    {
                        try { File.Delete(ipTxt); } catch { }
                        fileUrl = "";
                    }
                    if (!string.IsNullOrEmpty(fileUrl))
                    {
                        if (!fileUrl.StartsWith("http://") && !fileUrl.StartsWith("https://")) 
                        {
                            fileUrl = fileUrl.Contains(".") && !fileUrl.StartsWith("192.") && !fileUrl.StartsWith("127.")
                                ? "https://" + fileUrl 
                                : "http://" + fileUrl;
                        }
                        if (!fileUrl.Substring(fileUrl.IndexOf("//") + 2).Contains(":") && (fileUrl.Contains("127.0.0.1") || fileUrl.Contains("localhost")))
                        {
                            fileUrl = fileUrl + ":2005";
                        }
                        candidateUrls.Add(fileUrl.TrimEnd('/'));
                    }
                }
            }
            catch { }

            if (!string.IsNullOrEmpty(ServerHttpUrl) && !candidateUrls.Contains(ServerHttpUrl.TrimEnd('/'))) candidateUrls.Add(ServerHttpUrl.TrimEnd('/'));
            candidateUrls.Add("https://track.ektahr.com");
            candidateUrls.Add("http://127.0.0.1:2005");
            candidateUrls.Add("http://localhost:2005");

            if (!string.IsNullOrEmpty(userEnteredUrl) && !candidateUrls.Contains(userEnteredUrl.TrimEnd('/'))) candidateUrls.Add(userEnteredUrl.TrimEnd('/'));

            string discoveredUrl = DiscoverActiveLanServerUrl();
            if (!string.IsNullOrEmpty(discoveredUrl) && !candidateUrls.Contains(discoveredUrl)) candidateUrls.Add(discoveredUrl);

            candidateUrls.Add("http://192.168.0.31:2005");

            string localIp = GetLocalIPAddress();
            if (!string.IsNullOrEmpty(localIp)) candidateUrls.Add("http://" + localIp + ":2005");

            foreach (string targetUrl in candidateUrls)
            {
                if (string.IsNullOrEmpty(targetUrl)) continue;
                bool isSuccess = TryValidateAndRegisterSingle(email, password, targetUrl, out displayName, out errorMsg);
                if (isSuccess)
                {
                    ServerHttpUrl = targetUrl;
                    string wsScheme = targetUrl.StartsWith("https://") ? "wss://" : "ws://";
                    string domainAndPort = targetUrl.Replace("http://", "").Replace("https://", "");
                    ServerWsUrl = wsScheme + domainAndPort;
                    SaveLocalConfig(ServerHttpUrl, ServerWsUrl);
                    return true;
                }

                if (!string.IsNullOrEmpty(errorMsg) && (errorMsg.Contains("Invalid") || errorMsg.Contains("Login Blocked") || errorMsg.Contains("already logged in") || errorMsg.Contains("password") || errorMsg.Contains("credentials")))
                {
                    return false;
                }
            }

            if (string.IsNullOrEmpty(errorMsg) || errorMsg.StartsWith("Unable to connect"))
            {
                string displayTarget = (string.IsNullOrEmpty(ServerHttpUrl) || ServerHttpUrl.Contains("192.168") || ServerHttpUrl.Contains(":9000")) ? "https://track.ektahr.com" : ServerHttpUrl;
                errorMsg = "Unable to connect to server at " + displayTarget;
            }
            return false;
        }

        private static bool TryValidateAndRegisterSingle(string email, string password, string httpUrl, out string displayName, out string errorMsg)
        {
            displayName = email;
            errorMsg = "";

            try
            {
                System.Net.ServicePointManager.SecurityProtocol = (System.Net.SecurityProtocolType)3072 | System.Net.SecurityProtocolType.Tls11 | System.Net.SecurityProtocolType.Tls;
                string registerEndpoint = httpUrl.TrimEnd('/') + "/api/device/register";
                string hostname = Environment.MachineName;
                string deviceId = "WIN-PC-" + hostname.ToUpper();

                string jsonBody = "{" +
                    "\"email\":\"" + EscapeJson(email) + "\"," +
                    "\"password\":\"" + EscapeJson(password) + "\"," +
                    "\"deviceId\":\"" + EscapeJson(deviceId) + "\"," +
                    "\"machineName\":\"" + EscapeJson(hostname) + "\"," +
                    "\"osVersion\":\"Windows 11 x64\"," +
                    "\"agentVersion\":\"1.0.1\"," +
                    "\"systemIp\":\"127.0.0.1\"," +
                    "\"systemModel\":\"EktaHR Desktop Client\"" +
                    "}";

                byte[] bodyBytes = Encoding.UTF8.GetBytes(jsonBody);
                HttpWebRequest req = (HttpWebRequest)WebRequest.Create(registerEndpoint);
                req.Method = "POST";
                req.ContentType = "application/json";
                req.ContentLength = bodyBytes.Length;
                req.Timeout = 4000;

                using (Stream reqStream = req.GetRequestStream())
                {
                    reqStream.Write(bodyBytes, 0, bodyBytes.Length);
                }

                using (HttpWebResponse resp = (HttpWebResponse)req.GetResponse())
                {
                    using (StreamReader sr = new StreamReader(resp.GetResponseStream()))
                    {
                        string respText = sr.ReadToEnd();
                        if (respText.Contains("\"token\""))
                        {
                            DeviceToken = ExtractJsonValue(respText, "token");
                            displayName = email;
                            LoggedUser = email;
                            if (email.Contains("@")) EmployeeName = email.Split('@')[0];
                            BusinessId = ExtractJsonValue(respText, "businessId");
                            if (string.IsNullOrEmpty(BusinessId)) BusinessId = ExtractJsonValue(respText, "companyId");
                            if (string.IsNullOrEmpty(BusinessId)) BusinessId = "default";
                            return true;
                        }
                        else
                        {
                            errorMsg = ExtractJsonValue(respText, "error");
                            if (string.IsNullOrEmpty(errorMsg)) errorMsg = ExtractJsonValue(respText, "message");
                            if (string.IsNullOrEmpty(errorMsg)) errorMsg = "Authentication failed.";
                            return false;
                        }
                    }
                }
            }
            catch (WebException wex)
            {
                try
                {
                    if (wex.Response != null)
                    {
                        using (StreamReader sr = new StreamReader(wex.Response.GetResponseStream()))
                        {
                            string errJson = sr.ReadToEnd();
                            string msg = ExtractJsonValue(errJson, "error");
                            if (string.IsNullOrEmpty(msg)) msg = ExtractJsonValue(errJson, "message");
                            if (!string.IsNullOrEmpty(msg))
                            {
                                errorMsg = msg;
                                return false;
                            }
                        }
                    }
                }
                catch { }

                errorMsg = "Unable to connect to server at " + httpUrl;
                return false;
            }
            catch (Exception ex)
            {
                errorMsg = "Login error: " + ex.Message;
                return false;
            }
        }

        public static void StartSession(string user, string httpUrl, string wsUrl, string deviceId, string hostname)
        {
            IsLoggedIn = true;
            LoggedUser = user;
            ServerHttpUrl = httpUrl;
            ServerWsUrl = wsUrl;
            SaveLocalConfig(httpUrl, wsUrl);

            // Load Cumulative Daily Session Stats for User (preserves first CheckInTime of the day & accumulated shift seconds)
            LoadDailyStats(user);

            connCts = new CancellationTokenSource();

            string fullWsUrl = wsUrl.TrimEnd('/') + "/agent?deviceId=" + Uri.EscapeDataString(deviceId) +
                            "&hostname=" + Uri.EscapeDataString(hostname) +
                            "&user=" + Uri.EscapeDataString(user);

            Task.Run(() => ConnectionLoop(fullWsUrl, connCts.Token));
            Task.Run(() => SendHeartbeatHttpLoop(connCts.Token));
            Task.Run(() => PeriodicScreenshotLoop(connCts.Token));
            Task.Run(() => WorkTimerLoop(connCts.Token));
        }

        public static void StopSession()
        {
            try
            {
                SendInstantStatusUpdate("LOGGED_OUT");
            }
            catch { }

            IsLoggedIn = false;
            IsStreaming = false;
            CheckOutTime = DateTime.Now.ToString("hh:mm tt");
            SaveDailyStats();
            AgentStatus = "Logged Out";
            LiveStreamStatus = "Offline";

            try
            {
                if (!string.IsNullOrEmpty(DeviceToken))
                {
                    Task.Run(() =>
                    {
                        try
                        {
                            string endpoint = ServerHttpUrl.TrimEnd('/') + "/api/device/set-logout";
                            HttpWebRequest req = (HttpWebRequest)WebRequest.Create(endpoint);
                            req.Method = "POST";
                            req.ContentType = "application/json";
                            req.Headers.Add("Authorization", "Bearer " + DeviceToken);
                            req.Timeout = 2000;
                            using (Stream reqStream = req.GetRequestStream())
                            {
                                byte[] b = Encoding.UTF8.GetBytes("{}");
                                reqStream.Write(b, 0, b.Length);
                            }
                            using (HttpWebResponse resp = (HttpWebResponse)req.GetResponse()) { }
                        }
                        catch { }
                    });
                }
            }
            catch { }

            try
            {
                if (connCts != null)
                {
                    connCts.Cancel();
                    connCts.Dispose();
                    connCts = null;
                }

                if (currentWs != null)
                {
                    if (currentWs.State == WebSocketState.Open)
                    {
                        currentWs.CloseAsync(WebSocketCloseStatus.NormalClosure, "Logged out", CancellationToken.None).Wait(300);
                    }
                    currentWs.Dispose();
                    currentWs = null;
                }
            }
            catch { }
        }

