        public static uint GetIdleTimeMs()
        {
            try
            {
                LASTINPUTINFO lii = new LASTINPUTINFO();
                lii.cbSize = (uint)System.Runtime.InteropServices.Marshal.SizeOf(lii);
                lii.dwTime = 0;
                uint envTicks = (uint)Environment.TickCount;
                if (GetLastInputInfo(ref lii))
                {
                    return envTicks - lii.dwTime;
                }
            }
            catch { }
            return 0;
        }

        private static bool wasIdleState = false;

        private static async Task WorkTimerLoop(CancellationToken token)
        {
            int saveCounter = 0;
            while (!token.IsCancellationRequested && IsLoggedIn)
            {
                try
                {
                    RecalculateShiftSeconds();

                    uint idleMs = GetIdleTimeMs();
                    IdleSeconds = (int)(idleMs / 1000);

                    // If idle for 5+ minutes (300 seconds) without mouse movement, pause active time & notify
                    bool isSystemIdle = IdleSeconds >= 300;

                    if (isSystemIdle && !wasIdleState)
                    {
                        wasIdleState = true;
                        AgentStatus = "Idle";
                        SendInstantStatusUpdate("IDLE");
                        ShowIdleTrayNotification(true);
                    }
                    else if (!isSystemIdle && wasIdleState)
                    {
                        wasIdleState = false;
                        AgentStatus = "Active";
                        SendInstantStatusUpdate("ONLINE");
                        ShowIdleTrayNotification(false);
                    }

                    if (!IsPaused && !IsBreak && !IsMeeting && !isSystemIdle)
                    {
                        ActiveSeconds++;
                    }

                    saveCounter++;
                    if (saveCounter >= 5)
                    {
                        saveCounter = 0;
                        SaveDailyStats();
                    }
                }
                catch { }

                await Task.Delay(1000, token);
            }
        }

        private static void ShowIdleTrayNotification(bool isIdle)
        {
            try
            {
                if (EktaAgentForm.Instance != null && !EktaAgentForm.Instance.IsDisposed)
                {
                    EktaAgentForm.Instance.Invoke((Action)(() =>
                    {
                        if (isIdle)
                        {
                            EktaAgentForm.Instance.ShowTrayBalloon("ektaHr Monitoring: System Idle", "No mouse movement detected for 5 minutes. Active timer paused.", ToolTipIcon.Warning);
                        }
                        else
                        {
                            EktaAgentForm.Instance.ShowTrayBalloon("ektaHr Monitoring: Active Resumed", "Mouse movement detected. Active work timer resumed.", ToolTipIcon.Info);
                        }
                    }));
                }
            }
            catch { }
        }

