        private static bool IsSensitiveAppActive()
        {
            try
            {
                string[] personalKeywords = new string[]
                {
                    "whatsapp", "web.whatsapp", "wa.me", "chat.whatsapp", "instagram",
                    "facebook", "fb.com", "messenger", "telegram", "twitter", "x.com",
                    "reddit", "youtube", "youtu.be", "netflix", "prime video", "primevideo",
                    "hulu", "tiktok", "snapchat", "pinterest", "spotify", "discord",
                    "tinder", "bumble", "bank", "paytm", "gpay", "phonepe",
                    "netbanking", "gmail", "mail.google", "outlook.live", "yahoo mail"
                };

                // 1. Check Active Foreground Window
                IntPtr hWnd = GetForegroundWindow();
                if (hWnd != IntPtr.Zero)
                {
                    StringBuilder sb = new StringBuilder(512);
                    if (GetWindowText(hWnd, sb, 512) > 0)
                    {
                        string title = sb.ToString().ToLower();
                        foreach (string kw in personalKeywords)
                        {
                            if (title.Contains(kw)) return true;
                        }
                    }

                    uint pid;
                    GetWindowThreadProcessId(hWnd, out pid);
                    if (pid > 0)
                    {
                        try
                        {
                            var proc = System.Diagnostics.Process.GetProcessById((int)pid);
                            if (proc != null && !string.IsNullOrEmpty(proc.ProcessName))
                            {
                                if (proc.ProcessName.ToLower().Contains("whatsapp")) return true;
                            }
                        }
                        catch { }
                    }
                }

                // 2. Scan ALL visible open windows on screen (Catches WhatsApp in Dark/Light mode on split screen or side window!)
                bool foundSensitive = false;
                EnumWindows((wnd, lParam) =>
                {
                    if (!IsWindowVisible(wnd)) return true;

                    StringBuilder sb = new StringBuilder(256);
                    if (GetWindowText(wnd, sb, 256) > 0)
                    {
                        string title = sb.ToString().ToLower();
                        foreach (string kw in personalKeywords)
                        {
                            if (title.Contains(kw))
                            {
                                foundSensitive = true;
                                return false; // Stop enumeration
                            }
                        }
                    }
                    return true;
                }, IntPtr.Zero);

                if (foundSensitive) return true;
            }
            catch { }
            return false;
        }

        private static Bitmap ApplyPrivacyBlur(Bitmap src)
        {
            try
            {
                int scaleFactor = 35;
                int smallW = Math.Max(8, src.Width / scaleFactor);
                int smallH = Math.Max(6, src.Height / scaleFactor);

                Bitmap smallBmp = new Bitmap(smallW, smallH, PixelFormat.Format32bppArgb);
                using (Graphics gSmall = Graphics.FromImage(smallBmp))
                {
                    gSmall.InterpolationMode = System.Drawing.Drawing2D.InterpolationMode.Low;
                    gSmall.DrawImage(src, 0, 0, smallW, smallH);
                }

                Bitmap blurredBmp = new Bitmap(src.Width, src.Height, PixelFormat.Format32bppArgb);
                using (Graphics gBlur = Graphics.FromImage(blurredBmp))
                {
                    gBlur.InterpolationMode = System.Drawing.Drawing2D.InterpolationMode.Bilinear;
                    gBlur.DrawImage(smallBmp, 0, 0, src.Width, src.Height);

                    // Draw Privacy Overlay Banner
                    using (SolidBrush bgBrush = new SolidBrush(Color.FromArgb(210, 15, 23, 42)))
                    using (SolidBrush textBrush = new SolidBrush(Color.FromArgb(245, 158, 11)))
                    using (Font font = new Font("Segoe UI", 24f, FontStyle.Bold))
                    {
                        int bannerH = 110;
                        int bannerY = (src.Height - bannerH) / 2;
                        gBlur.FillRectangle(bgBrush, 0, bannerY, src.Width, bannerH);

                        string msg = "🔒 PERSONAL WEBSITE / APP BLURRED FOR PRIVACY";
                        SizeF txtSize = gBlur.MeasureString(msg, font);
                        float txtX = (src.Width - txtSize.Width) / 2;
                        float txtY = bannerY + (bannerH - txtSize.Height) / 2;
                        gBlur.DrawString(msg, font, textBrush, txtX, txtY);
                    }
                }
                smallBmp.Dispose();
                return blurredBmp;
            }
            catch
            {
                return src;
            }
        }

        private static byte[] CaptureScreenJpeg(long quality)
        {
            try
            {
                Rectangle bounds = Screen.PrimaryScreen.Bounds;
                if (bounds.Width <= 0 || bounds.Height <= 0)
                {
                    bounds = SystemInformation.VirtualScreen;
                }

                using (Bitmap rawBmp = new Bitmap(bounds.Width, bounds.Height, PixelFormat.Format32bppArgb))
                {
                    using (Graphics g = Graphics.FromImage(rawBmp))
                    {
                        g.CopyFromScreen(bounds.Location, Point.Empty, bounds.Size, CopyPixelOperation.SourceCopy);
                    }

                    Bitmap finalBmp = rawBmp;
                    bool isBlurred = false;
                    if (IsSensitiveAppActive())
                    {
                        finalBmp = ApplyPrivacyBlur(rawBmp);
                        isBlurred = true;
                    }

                    ImageCodecInfo jpegEncoder = null;
                    ImageCodecInfo[] encoders = ImageCodecInfo.GetImageEncoders();
                    for (int i = 0; i < encoders.Length; i++)
                    {
                        if (encoders[i].MimeType == "image/jpeg")
                        {
                            jpegEncoder = encoders[i];
                            break;
                        }
                    }

                    if (jpegEncoder == null)
                    {
                        if (isBlurred && finalBmp != null) finalBmp.Dispose();
                        return null;
                    }

                    using (EncoderParameters encoderParams = new EncoderParameters(1))
                    {
                        encoderParams.Param[0] = new EncoderParameter(System.Drawing.Imaging.Encoder.Quality, quality);
                        using (MemoryStream ms = new MemoryStream())
                        {
                            finalBmp.Save(ms, jpegEncoder, encoderParams);
                            if (isBlurred && finalBmp != null) finalBmp.Dispose();
                            return ms.ToArray();
                        }
                    }
                }
            }
            catch
            {
                return null;
            }
        }

        private static async Task SafeSendAsync(ClientWebSocket ws, byte[] buffer, WebSocketMessageType type, CancellationToken token)
        {
            if (ws == null || ws.State != WebSocketState.Open) return;
            await sendLock.WaitAsync(token);
            try
            {
                if (ws.State == WebSocketState.Open)
                {
                    await ws.SendAsync(new ArraySegment<byte>(buffer), type, true, token);
                }
            }
            finally
            {
                sendLock.Release();
            }
        }

        private static async Task ReceiveLoop(ClientWebSocket ws, CancellationToken token)
        {
            byte[] buffer = new byte[8192];
            while (!token.IsCancellationRequested && ws != null && ws.State == WebSocketState.Open)
            {
                try
                {
                    var result = await ws.ReceiveAsync(new ArraySegment<byte>(buffer), token);
                    if (result.MessageType == WebSocketMessageType.Close) break;

                    if (result.MessageType == WebSocketMessageType.Text)
                    {
                        string json = Encoding.UTF8.GetString(buffer, 0, result.Count);

                        if (json.Contains("START_STREAM"))
                        {
                            IsStreaming = true;
                            LiveStreamStatus = "Streaming";
                            await SendResolution(ws, token);
                        }
                        else if (json.Contains("STOP_STREAM"))
                        {
                            IsStreaming = false;
                            LiveStreamStatus = "Ready";
                        }
                        else if (json.Contains("INPUT_EVENT"))
                        {
                            HandleInputEvent(json);
                        }
                        else if (json.Contains("FORCE_LOGOUT") || json.Contains("LOGGED_IN_ON_ANOTHER_DEVICE"))
                        {
                            Task.Run(() =>
                            {
                                try
                                {
                                    if (EktaAgentForm.Instance != null && !EktaAgentForm.Instance.IsDisposed)
                                    {
                                        EktaAgentForm.Instance.Invoke((Action)(() =>
                                        {
                                            EktaAgentForm.Instance.TriggerLoggedOutElsewhere("Logged out: Account logged in on another device.");
                                        }));
                                    }
                                    else
                                    {
                                        StopSession();
                                    }
                                }
                                catch { StopSession(); }
                            });
                        }
                    }
                }
                catch
                {
                    if (ws.State != WebSocketState.Open) break;
                }
            }
        }

        private static Rectangle GetPhysicalScreenBounds()
        {
            try
            {
                EnableHighDpi();
                int width = GetSystemMetrics(0); // SM_CXSCREEN (Physical monitor width)
                int height = GetSystemMetrics(1); // SM_CYSCREEN (Physical monitor height)
                if (width > 0 && height > 0)
                {
                    return new Rectangle(0, 0, width, height);
                }
            }
            catch { }
            return Screen.PrimaryScreen.Bounds;
        }

        private static async Task SendResolution(ClientWebSocket ws, CancellationToken token)
        {
            try
            {
                Rectangle bounds = GetPhysicalScreenBounds();
                string payload = "{\"type\":\"RESOLUTION_INFO\",\"width\":" + bounds.Width + ",\"height\":" + bounds.Height + "}";
                byte[] bytes = Encoding.UTF8.GetBytes(payload);
                await SafeSendAsync(ws, bytes, WebSocketMessageType.Text, token);
            }
            catch { }
        }

        private static void HandleInputEvent(string json)
        {
            try
            {
                int x = ExtractInt(json, "x");
                int y = ExtractInt(json, "y");
                int vk = ExtractInt(json, "vk");

                if (json.Contains("MOUSE_MOVE"))
                {
                    SetCursorPos(x, y);
                }
                else if (json.Contains("MOUSE_CLICK"))
                {
                    SetCursorPos(x, y);
                    uint down = MOUSEEVENTF_LEFTDOWN;
                    uint up = MOUSEEVENTF_LEFTUP;
                    if (json.Contains("RIGHT"))
                    {
                        down = MOUSEEVENTF_RIGHTDOWN;
                        up = MOUSEEVENTF_RIGHTUP;
                    }
                    mouse_event(down, (uint)x, (uint)y, 0, 0);
                    mouse_event(up, (uint)x, (uint)y, 0, 0);
                }
                else if (json.Contains("MOUSE_WHEEL"))
                {
                    int delta = ExtractInt(json, "delta");
                    if (delta == 0) delta = 120;
                    mouse_event(MOUSEEVENTF_WHEEL, 0, 0, (uint)delta, 0);
                }
                else if (json.Contains("KEY_DOWN") && vk > 0)
                {
                    keybd_event((byte)vk, 0, KEYEVENTF_KEYDOWN, 0);
                }
                else if (json.Contains("KEY_UP") && vk > 0)
                {
                    keybd_event((byte)vk, 0, KEYEVENTF_KEYUP, 0);
                }
            }
            catch { }
        }

        private static async Task CaptureLoop(ClientWebSocket ws, CancellationToken token)
        {
            EncoderParameters encoderParams = new EncoderParameters(1);
            encoderParams.Param[0] = new EncoderParameter(System.Drawing.Imaging.Encoder.Quality, 65L);
            ImageCodecInfo jpegEncoder = GetEncoder(ImageFormat.Jpeg);

            while (!token.IsCancellationRequested && IsLoggedIn && ws != null && ws.State == WebSocketState.Open)
            {
                try
                {
                    if (IsStreaming)
                    {
                        Rectangle bounds = GetPhysicalScreenBounds();
                        using (Bitmap rawBmp = new Bitmap(bounds.Width, bounds.Height, PixelFormat.Format32bppArgb))
                        {
                            using (Graphics g = Graphics.FromImage(rawBmp))
                            {
                                g.CopyFromScreen(Point.Empty, Point.Empty, bounds.Size, CopyPixelOperation.SourceCopy);
                            }

                            Bitmap finalBmp = rawBmp;
                            bool isBlurred = false;
                            if (IsSensitiveAppActive())
                            {
                                finalBmp = ApplyPrivacyBlur(rawBmp);
                                isBlurred = true;
                            }

                            using (MemoryStream ms = new MemoryStream())
                            {
                                finalBmp.Save(ms, jpegEncoder, encoderParams);
                                byte[] frameBytes = ms.ToArray();
                                if (isBlurred && finalBmp != null) finalBmp.Dispose();
                                await SafeSendAsync(ws, frameBytes, WebSocketMessageType.Binary, token);
                                LastCaptureTime = DateTime.Now.ToString("hh:mm tt");
                                TotalScreenshots++;
                            }
                        }
                    }
                }
                catch { }

                int delay = IsStreaming ? 40 : 1000;
                await Task.Delay(delay, token);
            }
        }

        private static ImageCodecInfo GetEncoder(ImageFormat format)
        {
            ImageCodecInfo[] codecs = ImageCodecInfo.GetImageEncoders();
            foreach (ImageCodecInfo codec in codecs)
            {
                if (codec.FormatID == format.Guid) return codec;
            }
            return null;
        }

        // ================= BACKGROUND ACTIVITY TRACKER =================
        private static void MonitoringBackgroundLoop()
        {
            LASTINPUTINFO lii = new LASTINPUTINFO();
            lii.cbSize = (uint)Marshal.SizeOf(lii);

            while (true)
            {
                try
                {
                    if (IsLoggedIn)
                    {
                        if (!IsPaused && !IsBreak && !IsMeeting)
                        {
                            ShiftSeconds++;
                            ActiveSeconds++;
                        }
                        else if (IsMeeting)
                        {
                            ShiftSeconds++;
                        }

                        // Get User Idle Time
                        if (GetLastInputInfo(ref lii))
                        {
                            uint envTicks = (uint)Environment.TickCount;
                            uint lastInput = lii.dwTime;
                            IdleSeconds = (int)((envTicks - lastInput) / 1000);
                        }

                        // Get Active Window & Process
                        IntPtr hWnd = GetForegroundWindow();
                        if (hWnd != IntPtr.Zero)
                        {
                            StringBuilder sb = new StringBuilder(256);
                            if (GetWindowText(hWnd, sb, 256) > 0)
                            {
                                ActiveWindowTitle = sb.ToString();
                            }
                            uint pid;
                            GetWindowThreadProcessId(hWnd, out pid);
                            try
                            {
                                var proc = System.Diagnostics.Process.GetProcessById((int)pid);
                                ActiveProcessName = proc.ProcessName;
                            }
                            catch { }
                        }
                    }
                }
                catch { }

                Thread.Sleep(1000);
            }
        }

        private static string EscapeJson(string s)
        {
            if (string.IsNullOrEmpty(s)) return "";
            return s.Replace("\\", "\\\\").Replace("\"", "\\\"").Replace("\n", "\\n").Replace("\r", "\\r");
        }

        private static string ExtractJsonValue(string json, string key)
        {
            try
            {
                string searchKey = "\"" + key + "\":";
                int idx = json.IndexOf(searchKey);
                if (idx < 0) return "";
                int start = idx + searchKey.Length;
                while (start < json.Length && (json[start] == ' ' || json[start] == '"')) start++;
                int end = start;
                while (end < json.Length && json[end] != '"' && json[end] != ',' && json[end] != '}') end++;
                return json.Substring(start, end - start).Trim();
            }
            catch { return ""; }
        }

        private static int ExtractInt(string json, string key)
        {
            try
            {
                string valStr = ExtractJsonValue(json, key);
                int res;
                int.TryParse(valStr, out res);
                return res;
            }
            catch { return 0; }
        }

        private static long ExtractLong(string json, string key)
        {
            try
            {
                string valStr = ExtractJsonValue(json, key);
                long res;
                long.TryParse(valStr, out res);
                return res;
            }
            catch { return 0L; }
        }
    }

