    public class EktaToggleSwitch : Control
    {
        private bool _checked = false;
        public event EventHandler CheckedChanged;

        public bool Checked
        {
            get { return _checked; }
            set
            {
                if (_checked != value)
                {
                    _checked = value;
                    this.Invalidate();
                    if (CheckedChanged != null) CheckedChanged(this, EventArgs.Empty);
                }
            }
        }

        public EktaToggleSwitch()
        {
            this.SetStyle(ControlStyles.SupportsTransparentBackColor, true);
            this.DoubleBuffered = true;
            this.Size = new Size(46, 24);
            this.BackColor = Color.FromArgb(38, 38, 38);
            this.Cursor = Cursors.Hand;
            this.Click += (s, e) => { this.Checked = !this.Checked; };
        }

        protected override void OnPaint(PaintEventArgs e)
        {
            base.OnPaint(e);
            e.Graphics.SmoothingMode = SmoothingMode.AntiAlias;

            Rectangle rect = new Rectangle(0, 0, this.Width - 1, this.Height - 1);
            int radius = rect.Height / 2;
            using (GraphicsPath path = GetRoundedPath(rect, radius))
            {
                Color trackBg = _checked ? Color.FromArgb(245, 158, 11) : Color.FromArgb(55, 65, 81);
                using (SolidBrush brush = new SolidBrush(trackBg))
                {
                    e.Graphics.FillPath(brush, path);
                }
            }

            int knobDiameter = this.Height - 6;
            int knobX = _checked ? (this.Width - knobDiameter - 3) : 3;
            Rectangle knobRect = new Rectangle(knobX, 3, knobDiameter, knobDiameter);

            using (SolidBrush knobBrush = new SolidBrush(Color.White))
            {
                e.Graphics.FillEllipse(knobBrush, knobRect);
            }
        }

        private GraphicsPath GetRoundedPath(Rectangle rect, int radius)
        {
            GraphicsPath path = new GraphicsPath();
            int d = radius * 2;
            path.AddArc(rect.X, rect.Y, d, d, 180, 90);
            path.AddArc(rect.Right - d, rect.Y, d, d, 270, 90);
            path.AddArc(rect.Right - d, rect.Bottom - d, d, d, 0, 90);
            path.AddArc(rect.X, rect.Bottom - d, d, d, 90, 90);
            path.CloseFigure();
            return path;
        }
    }

    public class EktaCircularTimer : Control
    {
        private string _timeText = "00:00:00";
        public string TimeText
        {
            get { return _timeText; }
            set { _timeText = value; this.Invalidate(); }
        }

        public EktaCircularTimer()
        {
            this.SetStyle(ControlStyles.SupportsTransparentBackColor, true);
            this.DoubleBuffered = true;
            this.Size = new Size(180, 180);
            this.BackColor = Color.FromArgb(30, 30, 30);
        }

        protected override void OnPaint(PaintEventArgs e)
        {
            base.OnPaint(e);
            e.Graphics.SmoothingMode = SmoothingMode.AntiAlias;

            int margin = 10;
            Rectangle rect = new Rectangle(margin, margin, this.Width - margin * 2, this.Height - margin * 2);

            // Dark Ring Track
            using (Pen trackPen = new Pen(Color.FromArgb(55, 65, 81), 4.5f))
            {
                e.Graphics.DrawEllipse(trackPen, rect);
            }

            // Yellow Indicator Dot at 12 o'clock
            int dotRadius = 4;
            int dotX = this.Width / 2 - dotRadius;
            int dotY = margin - dotRadius;
            using (SolidBrush dotBrush = new SolidBrush(Color.FromArgb(239, 170, 31)))
            {
                e.Graphics.FillEllipse(dotBrush, dotX, dotY, dotRadius * 2, dotRadius * 2);
            }

            // Big Bold Amber Gold Timer Text
            using (Font font = new Font("Segoe UI", 22f, FontStyle.Bold))
            {
                TextRenderer.DrawText(
                    e.Graphics,
                    _timeText,
                    font,
                    rect,
                    Color.FromArgb(239, 170, 31),
                    TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter
                );
            }
        }
    }

