            this.Size = new Size(460, 680);
            this.StartPosition = FormStartPosition.CenterScreen;
            this.FormBorderStyle = FormBorderStyle.FixedSingle;
            this.MaximizeBox = false;
            this.BackColor = Color.FromArgb(30, 30, 30);
            this.ForeColor = Color.White;

            try
            {
                string explicitIco = @"d:\Projects\ektaHr\dma\agent\publish\ektaHr.ico";
                if (File.Exists(explicitIco)) this.Icon = new Icon(explicitIco);
                else this.Icon = Icon.ExtractAssociatedIcon(Application.ExecutablePath);
            }
            catch
            {
                try
                {
                    string icoPath = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "ektaHr.ico");
                    if (File.Exists(icoPath)) this.Icon = new Icon(icoPath);
                }
                catch { }
            }

            // System Tray Icon
            trayIcon = new NotifyIcon()
            {
                Icon = (this.Icon != null) ? this.Icon : SystemIcons.Application,
                Text = "ektaHr Attendance Monitoring",
                Visible = true
            };

            ContextMenuStrip trayMenu = new ContextMenuStrip();
            trayMenu.Items.Add("Open Monitoring Window", null, (s, e) => { this.Show(); this.WindowState = FormWindowState.Normal; });
            trayMenu.Items.Add("Pause Activity Tracking", null, (s, e) => { swPause.Checked = !swPause.Checked; });
            trayMenu.Items.Add("-");
            trayMenu.Items.Add("Exit", null, (s, e) => { trayIcon.Visible = false; Program.StopSession(); Application.Exit(); });
            trayIcon.ContextMenuStrip = trayMenu;
            trayIcon.DoubleClick += (s, e) => { this.Show(); this.WindowState = FormWindowState.Normal; };

            BuildAllViews();

            // UI Refresh Loop
            uiTimer = new System.Windows.Forms.Timer();
            uiTimer.Interval = 1000;
            uiTimer.Tick += (s, e) => UpdateUI();
            uiTimer.Start();

            // Default View
            SwitchToView("LOGIN");
        }

        protected override void OnShown(EventArgs e)
        {
            base.OnShown(e);
            this.WindowState = FormWindowState.Normal;
            this.BringToFront();
            this.Activate();
        }

        protected override void OnFormClosing(FormClosingEventArgs e)
        {
            if (Program.IsLoggedIn && e.CloseReason == CloseReason.UserClosing)
            {
                e.Cancel = true;
                this.Hide();
                if (trayIcon != null)
                {
                    trayIcon.ShowBalloonTip(3000, "ektaHr Monitoring", "Tracking is active in the background. Double-click tray icon to open.", ToolTipIcon.Info);
                }
                return;
            }
            if (trayIcon != null) trayIcon.Visible = false;
            base.OnFormClosing(e);
        }

        protected override void WndProc(ref Message m)
        {
            if (m.Msg == Program.WM_SHOW_EKTA_AGENT)
            {
                this.Show();
                this.WindowState = FormWindowState.Normal;
                this.BringToFront();
                this.Activate();
                if (Program.IsLoggedIn)
                {
                    SwitchToView("HOME");
                }
                return;
            }
            base.WndProc(ref m);
        }

