        private EktaCardPanel CreateMetricCard(string icon, string title, string defaultVal, string subtitle, int x, int y, out Label valLabel)
        {
            EktaCardPanel card = new EktaCardPanel()
            {
                Location = new Point(x, y),
                Size = new Size(190, 155),
                BorderRadius = 10,
                BackColor = Color.FromArgb(38, 38, 38)
            };

            Label lblIcon = new Label() { Text = icon, Font = new Font("Segoe UI Symbol", 12f), ForeColor = Color.FromArgb(239, 170, 31), Location = new Point(12, 12), Size = new Size(24, 24) };
            Label lblTitle = new Label() { Text = title, Font = new Font("Segoe UI", 10.5f, FontStyle.Bold), ForeColor = Color.White, Location = new Point(42, 12), AutoSize = true };

            valLabel = new Label()
            {
                Text = defaultVal,
                Font = new Font("Segoe UI", 20f, FontStyle.Bold),
                ForeColor = Color.FromArgb(239, 170, 31),
                Location = new Point(12, 48),
                Size = new Size(166, 40)
            };

            Label lblSub = new Label()
            {
                Text = subtitle,
                Font = new Font("Segoe UI", 8.5f),
                ForeColor = Color.FromArgb(156, 163, 175),
                Location = new Point(12, 98),
                Size = new Size(166, 40)
            };

            card.Controls.Add(lblIcon); card.Controls.Add(lblTitle);
            card.Controls.Add(valLabel); card.Controls.Add(lblSub);
            return card;
        }

        private void CreateDataRow(Control parent, string labelText, string valueText, int yPos, out Label valLabel)
        {
            Label lblKey = new Label()
            {
                Text = labelText,
                Font = new Font("Segoe UI", 9.5f),
                ForeColor = Color.FromArgb(156, 163, 175),
                Location = new Point(14, yPos),
                AutoSize = true
            };
            valLabel = new Label()
            {
                Text = valueText,
                Font = new Font("Segoe UI", 9.5f, FontStyle.Bold),
                ForeColor = Color.White,
                Location = new Point(120, yPos),
                Size = new Size(260, 24),
                TextAlign = ContentAlignment.TopRight
            };
            parent.Controls.Add(lblKey);
            parent.Controls.Add(valLabel);
        }

        private void SwitchToView(string viewName)
        {
            pnlLoginView.Visible = (viewName == "LOGIN");
            pnlHeader.Visible = (viewName != "LOGIN");
            pnlHomeView.Visible = (viewName == "HOME");
            pnlSummaryView.Visible = (viewName == "SUMMARY");
            pnlSettingsView.Visible = (viewName == "SETTINGS");

            lblNavHome.ForeColor = (viewName == "HOME") ? Color.FromArgb(239, 170, 31) : Color.FromArgb(156, 163, 175);
            lblNavSummary.ForeColor = (viewName == "SUMMARY") ? Color.FromArgb(239, 170, 31) : Color.FromArgb(156, 163, 175);
            lblNavSettings.ForeColor = (viewName == "SETTINGS") ? Color.FromArgb(239, 170, 31) : Color.FromArgb(156, 163, 175);
        }

        private void BtnLogin_Click(object sender, EventArgs e)
        {
            string email = txtEmail.Text.Trim();
            string pass = txtPassword.Text.Trim();

            if (string.IsNullOrEmpty(email) || string.IsNullOrEmpty(pass))
            {
                lblLoginError.Text = "Please enter both email and password.";
                return;
            }

            lblLoginError.Text = "Signing in...";
            Application.DoEvents();

            string displayName;
            string err;
            bool ok = Program.ValidateAndRegister(email, pass, "", out displayName, out err);

            if (!ok)
            {
                lblLoginError.Text = err;
                return;
            }

            lblLoginError.Text = "";
            Program.StartSession(displayName, Program.ServerHttpUrl, Program.ServerWsUrl, deviceId, hostname);

            SwitchToView("HOME");
            trayIcon.Text = "ektaHr Agent - Active (" + displayName + ")";
        }

        private void BtnLogout_Click(object sender, EventArgs e)
        {
            Program.StopSession();

            SwitchToView("LOGIN");
            lblLoginError.Text = "Logged out successfully.";
            trayIcon.Text = "ektaHr Agent - Logged Out";
        }

        public void TriggerLoggedOutElsewhere(string msg)
        {
            try
            {
                Program.StopSession();
                SwitchToView("LOGIN");
                if (lblLoginError != null) lblLoginError.Text = msg;
                if (trayIcon != null) trayIcon.Text = "ektaHr Agent - Logged Out";
                this.Show();
                this.WindowState = FormWindowState.Normal;
                this.BringToFront();
            }
            catch { }
        }

        public void ShowTrayBalloon(string title, string text, ToolTipIcon icon = ToolTipIcon.Info)
        {
            try
            {
                if (trayIcon != null)
                {
                    trayIcon.ShowBalloonTip(4000, title, text, icon);
                }
            }
            catch { }
        }

        private string FormatDuration(int totalSeconds)
        {
            if (totalSeconds < 60) return string.Format("{0}s", totalSeconds);
            int hrs = totalSeconds / 3600;
            int mins = (totalSeconds % 3600) / 60;
            if (hrs > 0) return string.Format("{0}h {1}m", hrs, mins);
            return string.Format("{0}m", mins);
        }

        private void UpdateUI()
        {
            if (Program.IsLoggedIn)
            {
                Program.RecalculateShiftSeconds();

                // Format Timer from Login Time to Current Time
                TimeSpan tsShift = TimeSpan.FromSeconds(Program.ShiftSeconds);
                int totalHours = (int)tsShift.TotalHours;
                circularTimer.TimeText = string.Format("{0:D2}:{1:D2}:{2:D2}", totalHours, tsShift.Minutes, tsShift.Seconds);

                // Format Today Card
                lblCheckedIn.Text = "Checked in at: " + Program.CheckInTime;
                lblCheckedOut.Text = "Checked out at: " + Program.CheckOutTime;
                lblStatusVal.Text = "Status: " + (Program.IsPaused ? "Paused" : (Program.IsBreak ? "Break" : (Program.IsMeeting ? "Meeting" : (Program.IdleSeconds >= 300 ? "Idle" : "Active"))));
                lblTotalWorkVal.Text = "Total Work: " + FormatDuration(Program.ShiftSeconds);
                lblIdleVal.Text = "Idle: " + FormatDuration(Program.IdleSeconds);
                lblActiveVal.Text = "Active: " + FormatDuration(Program.ActiveSeconds);
                lblLastCapture.Text = "Last capture: " + Program.LastCaptureTime;

                // Format Summary View
                lblSumWorkTime.Text = FormatDuration(Program.ShiftSeconds);
                lblSumActiveTime.Text = FormatDuration(Program.ActiveSeconds);
                lblSumIdleTime.Text = FormatDuration(Program.IdleSeconds);

                int prodPct = (Program.ShiftSeconds > 0) ? Math.Min(100, (int)((double)Program.ActiveSeconds / Program.ShiftSeconds * 100)) : 100;
                lblSumProductivity.Text = string.Format("{0}%", prodPct);
                lblSumFooter.Text = "Summary as of " + DateTime.Now.ToString("hh:mm tt");

                // Format Settings View
                lblProfName.Text = Program.EmployeeName;
                lblProfEmail.Text = Program.LoggedUser;
                lblProfStatus.Text = Program.AgentStatus;
            }
        }
    }
